from pathlib import Path
import re

p=Path('src/main.js')
s=p.read_text(encoding='utf-8')

# Include continuous thinking in motion/manual arbitration.
s=s.replace("['walk','run','wave','think','reach','weight','nod']", "['walk','run','wave','think','thinkLoop','reach','weight','nod']", 1)

# Full expression surface: presets plus every expression exposed by this VRM.
expr_pat=re.compile(r"function renderExpressionControls\(\)\{.*?\n\}\nfunction renderLifeControls", re.S)
expr_new=r'''function renderExpressionControls(){
  const presets=[['自然','neutral'],['微笑','happy'],['开心','happy'],['悲伤','sad'],['生气','angry'],['惊讶','surprised'],['放松','relaxed'],['眨眼','blink']];
  const mgr=vrm?.expressionManager;const dyn=[...new Set([...(mgr?.expressions||[]).map(e=>e.expressionName||e.name).filter(Boolean),...Object.keys(mgr?.expressionMap||{})])];
  controlPage.innerHTML=`<section class="panel-section"><h3>预设表情</h3><div class="button-grid">${presets.map(([l,n])=>`<button data-exp="${n}" class="secondary-btn">${l}</button>`).join('')}</div>${rowSlider('表情强度',0,1,.05,.7)}<button id="clearExp" class="secondary-btn wide">清除表情</button></section><details class="bone-group"><summary>全部 Expression · ${dyn.length}</summary><div id="allExpressions"></div></details>`;
  const slider=controlPage.querySelector('.panel-section input[type=range]');controlPage.querySelectorAll('[data-exp]').forEach(b=>{const exists=!mgr||dyn.length===0||dyn.includes(b.dataset.exp);b.disabled=!exists;b.onclick=()=>setExpression(b.dataset.exp,Number(slider.value),220);});$('#clearExp').onclick=()=>{for(const n of dyn)mgr?.setValue?.(n,0);setExpression('neutral',0,180);};
  const box=$('#allExpressions');for(const name of dyn){const wrap=document.createElement('div');wrap.innerHTML=rowSlider(name,0,1,.01,0);const r=wrap.querySelector('input');r.oninput=()=>{mgr.setValue(name,Number(r.value));wrap.querySelector('output').textContent=r.value;};box.appendChild(wrap);}
}
function renderLifeControls'''
s,n=expr_pat.subn(expr_new,s,count=1)
if n!=1: raise SystemExit('expression controls replacement failed')

# Add full material controls to the model page.
needle="  controlPage.innerHTML=html;bindToggles();\n  const modelRanges="
replacement="""  html+='<details class=\"bone-group\"><summary>全部材质控制</summary><div id=\"materialControls\"></div></details>';
  controlPage.innerHTML=html;bindToggles();
  const modelRanges="""
if needle not in s: raise SystemExit('body material insertion marker missing')
s=s.replace(needle,replacement,1)
needle2="  controlPage.querySelectorAll('[data-reset-bone]').forEach(b=>b.onclick=()=>{manualOffsets.delete(b.dataset.resetBone);renderBodyControls();});$('#bodyReset').onclick=()=>{manualOffsets.clear();renderBodyControls();};$('#modelReset').onclick=()=>{manualOffsets.clear();Object.assign(settings,{modelScale:1,modelX:0,modelY:0,modelZ:0,modelRotY:0,skinBrightness:1});applyModelSettings();saveSettings();renderBodyControls();};\n}"
replacement2="""  controlPage.querySelectorAll('[data-reset-bone]').forEach(b=>b.onclick=()=>{manualOffsets.delete(b.dataset.resetBone);renderBodyControls();});$('#bodyReset').onclick=()=>{manualOffsets.clear();renderBodyControls();};$('#modelReset').onclick=()=>{manualOffsets.clear();Object.assign(settings,{modelScale:1,modelX:0,modelY:0,modelZ:0,modelRotY:0,skinBrightness:1});applyModelSettings();saveSettings();renderBodyControls();};
  const mc=$('#materialControls');if(mc){for(const snap of materialSnapshots.values()){const m=snap.mat,card=document.createElement('div');card.className='material-card';let h=`<b>${snap.name}</b>`;if(m.color)h+=`<label class=\"color-row\"><span>颜色</span><input type=\"color\" value=\"#${m.color.getHexString()}\" data-kind=\"color\"></label>`;if(typeof m.opacity==='number')h+=rowSlider('透明度',0,1,.01,m.opacity);if(typeof m.roughness==='number')h+=rowSlider('粗糙度',0,1,.01,m.roughness);if(typeof m.metalness==='number')h+=rowSlider('金属度',0,1,.01,m.metalness);card.innerHTML=h;const c=card.querySelector('[data-kind=color]');if(c)c.oninput=e=>{m.color.set(e.target.value);m.needsUpdate=true;};const rr=[...card.querySelectorAll('input[type=range]')];let i=0;if(typeof m.opacity==='number'){const e=rr[i++];e.oninput=()=>{m.opacity=+e.value;m.transparent=m.opacity<1;e.parentElement.querySelector('output').textContent=e.value;m.needsUpdate=true;};}if(typeof m.roughness==='number'){const e=rr[i++];e.oninput=()=>{m.roughness=+e.value;e.parentElement.querySelector('output').textContent=e.value;};}if(typeof m.metalness==='number'){const e=rr[i++];e.oninput=()=>{m.metalness=+e.value;e.parentElement.querySelector('output').textContent=e.value;};}mc.appendChild(card);}}
}"""
if needle2 not in s: raise SystemExit('body controls tail marker missing')
s=s.replace(needle2,replacement2,1)

# Stage: floor, rings, colors and material properties.
stage_pat=re.compile(r"function renderStageControls\(\)\{.*?\}\nfunction renderLightControls",re.S)
stage_new=r'''function renderStageControls(){controlPage.innerHTML=`<section class="panel-section"><h3>舞台总控</h3>${toggleHtml('显示舞台','stageVisible')}${rowSlider('舞台半径',.6,3,.05,1.55)}${rowSlider('地板透明度',0,1,.01,floorMat.opacity)}${rowSlider('地板粗糙度',0,1,.01,floorMat.roughness)}${rowSlider('地板金属度',0,1,.01,floorMat.metalness)}${rowSlider('主圆环亮度',0,1,.01,ringMat.opacity)}${rowSlider('内圆环亮度',0,1,.01,innerRing.material.opacity)}<label class="color-row"><span>背景颜色</span><input id="bgColor" type="color" value="#${scene.background.getHexString()}"></label><label class="color-row"><span>地板颜色</span><input id="floorColor" type="color" value="#${floorMat.color.getHexString()}"></label><label class="color-row"><span>主圆环颜色</span><input id="ringColor" type="color" value="#${ringMat.color.getHexString()}"></label><label class="color-row"><span>内圆环颜色</span><input id="innerColor" type="color" value="#${innerRing.material.color.getHexString()}"></label><button id="stageReset" class="secondary-btn wide">舞台复位</button></section>`;bindToggles();const vis=controlPage.querySelector('[data-setting="stageVisible"]');vis.onchange=e=>{settings.stageVisible=e.target.checked;floor.visible=ring.visible=innerRing.visible=settings.stageVisible;saveSettings();};const a=[...controlPage.querySelectorAll('input[type=range]')];a[0].oninput=()=>{const z=+a[0].value/1.55;floor.scale.setScalar(z);ring.scale.setScalar(z);innerRing.scale.setScalar(z);a[0].parentElement.querySelector('output').textContent=a[0].value;};a[1].oninput=()=>{floorMat.opacity=+a[1].value;a[1].parentElement.querySelector('output').textContent=a[1].value;};a[2].oninput=()=>{floorMat.roughness=+a[2].value;a[2].parentElement.querySelector('output').textContent=a[2].value;};a[3].oninput=()=>{floorMat.metalness=+a[3].value;a[3].parentElement.querySelector('output').textContent=a[3].value;};a[4].oninput=()=>{ringMat.opacity=+a[4].value;a[4].parentElement.querySelector('output').textContent=a[4].value;};a[5].oninput=()=>{innerRing.material.opacity=+a[5].value;a[5].parentElement.querySelector('output').textContent=a[5].value;};$('#bgColor').oninput=e=>{scene.background.set(e.target.value);renderer.setClearColor(e.target.value);};$('#floorColor').oninput=e=>floorMat.color.set(e.target.value);$('#ringColor').oninput=e=>ringMat.color.set(e.target.value);$('#innerColor').oninput=e=>innerRing.material.color.set(e.target.value);$('#stageReset').onclick=()=>{floor.scale.setScalar(1);ring.scale.setScalar(1);innerRing.scale.setScalar(1);floorMat.opacity=.94;floorMat.roughness=.78;floorMat.metalness=.08;ringMat.opacity=.75;innerRing.material.opacity=.32;scene.background.set(0x0b0d0e);renderer.setClearColor(0x0b0d0e);floorMat.color.set(0x10161d);ringMat.color.set(0x59dce0);innerRing.material.color.set(0x5665a7);renderStageControls();};}
function renderLightControls'''
s,n=stage_pat.subn(stage_new,s,count=1)
if n!=1: raise SystemExit('stage replacement failed')

# Lighting: all lights + positions/colors + spotlight optics + renderer exposure/shadows/pixel ratio.
light_pat=re.compile(r"function renderLightControls\(\)\{.*?\nfunction applyLighting\(\)\{.*?\}\nfunction applyLightPreset\(p\)\{.*?\}\nfunction renderCameraControls",re.S)
light_new=r'''function renderLightControls(){controlPage.innerHTML=`<section class="panel-section"><h3>灯光总控</h3><div class="preset-row"><button data-light="natural">自然</button><button data-light="soft">柔和</button><button data-light="warm">暖色</button><button data-light="cool">冷色</button><button data-light="stage">舞台</button></div>${rowSlider('环境光',0,2,.01,settings.ambient)}${rowSlider('主光',0,4,.01,settings.key)}<label class="color-row"><span>主光颜色</span><input id="keyColor" type="color" value="${settings.keyColor}"></label>${rowSlider('主光 X',-6,6,.1,settings.keyX)}${rowSlider('主光 Y',-2,8,.1,settings.keyY)}${rowSlider('主光 Z',-6,6,.1,settings.keyZ)}${rowSlider('补光',0,3,.01,settings.fill)}<label class="color-row"><span>补光颜色</span><input id="fillColor" type="color" value="${settings.fillColor}"></label>${rowSlider('补光 X',-6,6,.1,settings.fillX)}${rowSlider('补光 Y',-2,8,.1,settings.fillY)}${rowSlider('补光 Z',-6,6,.1,settings.fillZ)}${rowSlider('轮廓光',0,3,.01,settings.rim)}<label class="color-row"><span>轮廓颜色</span><input id="rimColor" type="color" value="${settings.rimColor}"></label>${rowSlider('轮廓 X',-6,6,.1,settings.rimX)}${rowSlider('轮廓 Y',-2,8,.1,settings.rimY)}${rowSlider('轮廓 Z',-6,6,.1,settings.rimZ)}${rowSlider('舞台聚光',0,8,.01,settings.stageLight)}<label class="color-row"><span>舞台灯颜色</span><input id="spotColor" type="color" value="${settings.stageColor}"></label>${rowSlider('聚光 X',-6,6,.1,settings.spotX)}${rowSlider('聚光 Y',0,10,.1,settings.spotY)}${rowSlider('聚光 Z',-6,6,.1,settings.spotZ)}${rowSlider('目标 X',-3,3,.1,settings.spotTargetX)}${rowSlider('目标 Y',0,3,.1,settings.spotTargetY)}${rowSlider('目标 Z',-3,3,.1,settings.spotTargetZ)}${rowSlider('聚光角度',.1,1.2,.01,settings.spotAngle)}${rowSlider('边缘柔和',0,1,.01,settings.spotPenumbra)}${rowSlider('距离',1,20,.1,settings.spotDistance)}${rowSlider('曝光',.5,1.5,.01,settings.exposure)}<label class="switch-row"><span>阴影</span><input id="shadowToggle" type="checkbox" ${renderer.shadowMap.enabled?'checked':''}></label><label>像素倍率<select id="pixelRatio"><option value="auto">Auto</option><option value="1">1x</option><option value="1.5">1.5x</option><option value="2">2x</option></select></label></section>`;const keys=['ambient','key','keyX','keyY','keyZ','fill','fillX','fillY','fillZ','rim','rimX','rimY','rimZ','stageLight','spotX','spotY','spotZ','spotTargetX','spotTargetY','spotTargetZ','spotAngle','spotPenumbra','spotDistance','exposure'];const ranges=[...controlPage.querySelectorAll('input[type=range]')];ranges.forEach((el,i)=>el.oninput=()=>{settings[keys[i]]=+el.value;el.parentElement.querySelector('output').textContent=el.value;applyLighting();saveSettings();});for(const [id,k] of [['keyColor','keyColor'],['fillColor','fillColor'],['rimColor','rimColor'],['spotColor','stageColor']])$('#'+id).oninput=e=>{settings[k]=e.target.value;applyLighting();saveSettings();};$('#shadowToggle').onchange=e=>renderer.shadowMap.enabled=e.target.checked;$('#pixelRatio').onchange=e=>{renderer.setPixelRatio(e.target.value==='auto'?Math.min(devicePixelRatio||1,2):+e.target.value);resize();};controlPage.querySelectorAll('[data-light]').forEach(b=>b.onclick=()=>applyLightPreset(b.dataset.light));}
function applyLighting(){ambient.intensity=settings.ambient;key.intensity=settings.key;fill.intensity=settings.fill;rim.intensity=settings.rim;stageSpot.intensity=settings.stageLight;key.color.set(settings.keyColor);fill.color.set(settings.fillColor);rim.color.set(settings.rimColor);stageSpot.color.set(settings.stageColor);key.position.set(settings.keyX,settings.keyY,settings.keyZ);fill.position.set(settings.fillX,settings.fillY,settings.fillZ);rim.position.set(settings.rimX,settings.rimY,settings.rimZ);stageSpot.position.set(settings.spotX,settings.spotY,settings.spotZ);stageSpot.target.position.set(settings.spotTargetX,settings.spotTargetY,settings.spotTargetZ);stageSpot.angle=settings.spotAngle;stageSpot.penumbra=settings.spotPenumbra;stageSpot.distance=settings.spotDistance;renderer.toneMappingExposure=settings.exposure;}
function applyLightPreset(p){const m={natural:[.32,1.15,.42,.55,0,.9],soft:[.42,.85,.55,.35,0,.9],warm:[.28,1.25,.35,.5,0,.88],cool:[.25,1,.6,.75,0,.88],stage:[.18,.8,.25,.8,2.2,.82]}[p];if(!m)return;[settings.ambient,settings.key,settings.fill,settings.rim,settings.stageLight,settings.exposure]=m;if(p==='warm'){settings.keyColor='#ffddc7';settings.fillColor='#ffd9c8';}else if(p==='cool'){settings.keyColor='#dceaff';settings.fillColor='#a6d9ff';}else{settings.keyColor='#fff4eb';settings.fillColor='#bfdcff';}applyLighting();saveSettings();renderLightControls();}
function renderCameraControls'''
s,n=light_pat.subn(light_new,s,count=1)
if n!=1: raise SystemExit('light replacement failed')

# Camera: presets plus all meaningful Orbit/Perspective settings.
cam_pat=re.compile(r"function renderCameraControls\(\)\{.*?\}\nfunction cameraPreset",re.S)
cam_new=r'''function renderCameraControls(){controlPage.innerHTML=`<section class="panel-section"><h3>相机总控</h3><div class="button-grid"><button data-cam="full">全身</button><button data-cam="upper">半身</button><button data-cam="face">脸部</button><button data-cam="left">左侧</button><button data-cam="right">右侧</button><button data-cam="back">背面</button></div>${rowSlider('FOV',15,70,1,camera.fov)}${rowSlider('旋转速度',.1,2,.05,controls.rotateSpeed)}${rowSlider('缩放速度',.1,2,.05,controls.zoomSpeed)}${rowSlider('平移速度',.1,2,.05,controls.panSpeed)}${rowSlider('阻尼',0,.25,.01,controls.dampingFactor)}${rowSlider('最小距离',.3,5,.1,controls.minDistance)}${rowSlider('最大距离',2,15,.1,controls.maxDistance)}${rowSlider('相机 X',-8,8,.05,camera.position.x)}${rowSlider('相机 Y',-2,8,.05,camera.position.y)}${rowSlider('相机 Z',-8,8,.05,camera.position.z)}${rowSlider('目标 X',-3,3,.05,controls.target.x)}${rowSlider('目标 Y',0,3,.05,controls.target.y)}${rowSlider('目标 Z',-3,3,.05,controls.target.z)}</section>`;controlPage.querySelectorAll('[data-cam]').forEach(b=>b.onclick=()=>{cameraPreset(b.dataset.cam);renderCameraControls();});const q=[...controlPage.querySelectorAll('input[type=range]')];const apply=()=>{camera.fov=+q[0].value;camera.updateProjectionMatrix();controls.rotateSpeed=+q[1].value;controls.zoomSpeed=+q[2].value;controls.panSpeed=+q[3].value;controls.dampingFactor=+q[4].value;controls.minDistance=+q[5].value;controls.maxDistance=+q[6].value;camera.position.set(+q[7].value,+q[8].value,+q[9].value);controls.target.set(+q[10].value,+q[11].value,+q[12].value);controls.update();q.forEach(e=>e.parentElement.querySelector('output').textContent=e.value);};q.forEach(e=>e.oninput=apply);}
function cameraPreset'''
s,n=cam_pat.subn(cam_new,s,count=1)
if n!=1: raise SystemExit('camera replacement failed')

# Apply persisted lighting/stage settings on boot.
s=s.replace("function animate(){", "applyLighting();floor.visible=ring.visible=innerRing.visible=settings.stageVisible!==false;\nfunction animate(){",1)
s=s.replace("version:'0.91-free-life'", "version:'0.92-free-life'",1)
p.write_text(s,encoding='utf-8')

css=Path('src/style.css')
c=css.read_text(encoding='utf-8')
if 'material-card' not in c:
    c += '\n.material-card{border-top:1px solid #153544;padding:9px;display:flex;flex-direction:column;gap:7px}.material-card>b{font-size:12px;color:#83ece9;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.panel-section select{border:1px solid #2b5264;background:#0a1620;border-radius:9px;padding:9px}\n'
css.write_text(c,encoding='utf-8')
